const RYAN_PID_LIBRARY_CATEGORY = 'P&IDs — Drawing-by-Drawing Index';
function normalizeEquipmentTag(value) { const s=safeString(value||'',80).trim().toUpperCase().replace(/[\u2010-\u2015]/g,'-').replace(/\s+/g,''); const m=s.match(/^([A-Z]{1,6})-?(\d{2,5}[A-Z]?)$/); return m?`${m[1]}-${m[2]}`:s; }
function equipmentTagPrefix(value){const m=normalizeEquipmentTag(value).match(/^([A-Z]+)/);return m?m[1]:'';}
function descriptionSystem(text,parentTag){const t=String(text||''),p=normalizeEquipmentTag(parentTag);const defs=[[/\bHOT\s*OIL\b|\bH-?7100\b|\bV-?7500\b|\bP-?7410\b|\bP-?7420\b/i,'hot_oil','Hot Oil','Hot Oil System'],[/\bFUEL\s*GAS\b|\bSEAL\s*GAS\b|\bV-?1460\b|\bE-?1227\b/i,'fuel_seal_gas','Fuel & Seal Gas','Utilities & Drains'],[/\bREGEN(?:ERATION)?\b|\bH-?1711\b|\bC-?1111\b/i,'regen','Regen','Dehydration & Regen'],[/\bDEHY(?:DRATION)?\b|\bMOLECULAR\s+SIEVE\b|\bV-?141[345]\b|\bF-?141[267]\b/i,'dehy','Dehydration','Dehydration & Regen'],[/\bREFRIG(?:ERATION)?\b|\bFRICK\b|\bPROPANE\b|\bV-?144[124]\b|\bC-?114[012]\b/i,'refrigeration','Refrigeration','Refrigeration (Propane)'],[/\bRESIDUE\b|\bC-?6[123]00\b|\bF-?6800\b/i,'residue_compression','Residue Compression','Residue Compression'],[/\bINLET\s+COMP(?:RESSION|RESSOR)?\b|\bC-?4[12]00\b/i,'inlet_compression','Inlet Compression','Inlet Compression'],[/\bPLANT\s+INLET\b|\bSLUG\s*CATCH(?:ER|ING)\b|\bV-?10(?:00|20|25|30|40)\b/i,'plant_inlet','Plant Inlet / Slug Catching','Slug Catchers & Inlet'],[/\bEXPANDER\b|\bBOOST(?:ER)?\s+COMP\b|\bEX-?1121\b|\bGAS\s*\/\s*GAS\b|\bCOLD\s+SEP(?:ARATOR)?\b/i,'expander_booster','Cryo / Expander / Gas-Gas','Cryo / Gas-Gas / Reflux'],[/\bDEMETH(?:ANIZER)?\b|\bT-?1521\b|\bREBOILER\b/i,'demethanizer','Demethanizer / Reboilers','Demethanizer & Reboilers'],[/\bSTABILIZER\b|\bT-?5030\b|\bV-?5010\b/i,'stabilizer','Stabilizer','Inlet Stabilizer'],[/\bNGL\b|\bV-?1422\b|\bP-?16(?:19|20|30|35)\b/i,'ngl_product','NGL Product','NGL Product / Pipeline'],[/\bINSTRUMENT\s+AIR\b|\bPK-?9200\b|\bV-?9241\b/i,'instrument_air','Instrument Air','Utilities & Drains'],[/\bCLOSED\s+DRAIN\b|\bCOLD\s+DRAIN\b|\bV-?8100\b|\bV-?1650\b/i,'drains','Drain Systems','Utilities & Drains'],[/\bFLARE\b|\bRELIEF\b|\bV-?8110\b|\bFL-?9110\b/i,'flare_relief','Flare / Relief','Utilities & Drains']];for(const d of defs)if(d[0].test(t)||d[0].test(p))return {id:d[1],title:d[2],category:d[3]};return {id:'',title:'',category:''};}
